SQL_DOC.P_SQL:
SELECT NVL(B.STATUS ,' ') AS STATUS, NVL(B.LEGACY_PO_NO ,' ') AS LEGACY_PO_NO, NVL(B.LEGACY_PO_SEQ ,' ') AS LEGACY_PO_SEQ, NVL(B.REF_IF_NO ,' ') AS LEGACY_PR_NO, NVL(REPLACE(C.IRS_NO,'-',''),' ') AS SELLER_IRS, NVL(SUBSTRB(MAX(C.COM_NAME_LOC),1,20),' ') AS SELLER_NAME FROM ICOMPOHD A, ICOMPODT B, ICOMCMPY C, ICOMLUSR D WHERE A.BUYER = '$G_RS.BUYER$' AND A.PO_NO = '$G_RS.PO_NO$' AND B.BUYER = A.BUYER AND B.PO_NO = A.PO_NO AND A.AGENT = C.COM_CODE AND C.COM_CODE = D.COM_CODE GROUP BY B.STATUS,B.BUYER,B.PO_NO,B.PO_SEQ,B.LEGACY_PO_NO,B.LEGACY_PO_SEQ,B.REF_IF_NO,A.AGENT,C.IRS_NO,C.TEL_NO
DECLARE
V_SEND_DATE ICOMPORS.SEND_DATE%TYPE; V_SEND_TIME ICOMPORS.SEND_TIME%TYPE; V_SEND_DATETIME ICOMTRXL.KEY_8%TYPE;
BEGIN
SELECT TO_CHAR(SYSDATE,'YYYYMMDD'), TO_CHAR(SYSDATE,'HH24MISS'), TO_CHAR(SYSDATE,'YYYYMMDD HH24MISS') INTO V_SEND_DATE, V_SEND_TIME, V_SEND_DATETIME FROM DUAL;
UPDATE ICOMPOHD SET SEND_DATE = V_SEND_DATE, SEND_TIME = V_SEND_TIME WHERE BUYER = '$G_RS.BUYER$' AND PO_NO = '$G_RS.PO_NO$' AND TRIM(SEND_DATE) IS NULL ;
UPDATE ICOMPODT SET SEND_DATE = V_SEND_DATE, SEND_TIME = V_SEND_TIME WHERE BUYER = '$G_RS.BUYER$' AND PO_NO = '$G_RS.PO_NO$' AND TRIM(SEND_DATE) IS NULL ;
UPDATE ICOMTRXL SET KEY_9 = 'D', KEY_8 = V_SEND_DATETIME WHERE DOC_NAME = 'CTDOWN' AND TARGET = '$G_RS.BUYER$' AND KEY_1 = '$G_RS.PO_NO$' AND TRIM(KEY_9) IS NULL ;
END;
UPDATE ICOMTRXL SET KEY_9 = 'E', KEY_8 = TO_CHAR(SYSDATE,'YYYYMMDD HH24MISS') WHERE DOC_NAME = 'CTDOWN' AND TARGET = '$G_RS.BUYER$' AND KEY_1 = '$G_RS.PO_NO$' AND TRIM(KEY_9) IS NULL
